def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)

    if not alive_opps:
        base = DAILY_SALARY * 0.35
        if hp <= 2 or no_water >= 1:
            base = DAILY_SALARY * 0.75
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    max_prev_bid = 0.0
    desperate_threat = 0.0
    rich_high = 0

    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        pbid = prev.get('bid')
        if pbid is not None:
            prev_bids.append(float(pbid))
            if float(pbid) > max_prev_bid:
                max_prev_bid = float(pbid)
        if opp.get('budget', 0) >= 120:
            rich_high += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_threat = max(desperate_threat, max(float(pbid) if pbid is not None else 0.0, DAILY_SALARY * 0.85))

    capacity = supply / float(WATER_REQ)
    tight_supply = capacity < (len(alive_opps) + 1)
    very_tight = capacity < len(alive_opps)

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 2
    if very_tight:
        urgency += 2
    elif tight_supply:
        urgency += 1

    if max_prev_bid <= 0:
        if urgency >= 4:
            bid = DAILY_SALARY * 0.95
        elif urgency >= 2:
            bid = DAILY_SALARY * 0.72
        else:
            bid = DAILY_SALARY * 0.45
        return float(max(0.0, min(budget, bid)))

    if urgency >= 5:
        target = max(max_prev_bid + 2.5, desperate_threat + 1.5, DAILY_SALARY * 1.95)
    elif urgency >= 3:
        target = max(max_prev_bid + 1.6, desperate_threat + 1.0, DAILY_SALARY * 1.45)
    elif urgency >= 1:
        target = max(max_prev_bid + 0.8, DAILY_SALARY * 1.0)
    else:
        if max_prev_bid >= DAILY_SALARY * 1.9 and hp >= 7 and no_water == 0 and not very_tight:
            target = DAILY_SALARY * 0.38
        elif max_prev_bid >= DAILY_SALARY * 1.6 and hp >= 6 and no_water == 0:
            target = DAILY_SALARY * 0.55
        else:
            target = max_prev_bid * 0.72

    if rich_high >= 2 and tight_supply and urgency >= 2:
        target += 2.0

    reserve_days = max(0, 10 - int(day))
    soft_cap = budget
    if reserve_days > 0 and urgency <= 2:
        soft_cap = min(soft_cap, budget / 2.0 + DAILY_SALARY * 0.5)
    elif reserve_days > 0 and urgency <= 4:
        soft_cap = min(soft_cap, budget * 0.72 + DAILY_SALARY * 0.5)

    hard_cap = budget
    bid = min(target, soft_cap, hard_cap)

    if hp <= 2 or no_water >= 2:
        bid = min(hard_cap, max(bid, min(hard_cap, max_prev_bid + 2.0, DAILY_SALARY * 1.7)))

    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append(o)

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.4))

    yesterday_bids = []
    for o in alive:
        prev = o.get('previous_trace', None) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how competitive the market is; Cindy's behavior implies others may chase.
    # If someone previously bid very high, we raise our bid to avoid being starved.
    pressure = 0.0
    if highest_prev_bid >= DAILY_SALARY * 1.2:
        pressure = 1.0
    elif highest_prev_bid >= DAILY_SALARY * 0.8:
        pressure = 0.6
    else:
        pressure = 0.3

    # Supply pressure: lower supply increases chance of losing water.
    supply_mid = (MIN_SUPPLY + MAX_SUPPLY) / 2.0
    supply_pressure = 0.0
    if supply <= supply_mid:
        supply_pressure = 0.6
    else:
        supply_pressure = 0.3

    # If I'm already low HP or have consecutive no-water days, bid more.
    urgency = 0.0
    if hp <= 2:
        urgency = 1.0
    elif hp <= 4:
        urgency = 0.7
    else:
        urgency = 0.4

    if no_water_days >= 2:
        urgency = min(1.0, urgency + 0.3)

    # Core bid target.
    # Aim to be competitive when pressure is high, but not max out unless critical.
    base = DAILY_SALARY * (0.45 + 0.25 * pressure + 0.15 * supply_pressure)
    if urgency >= 0.9:
        target = DAILY_SALARY * (0.85 + 0.1 * pressure)
    else:
        target = base + (highest_prev_bid * 0.05 if highest_prev_bid > 0 else 0.0)

    # Keep within reasonable bounds relative to supply.
    # If supply is very low, we increase slightly.
    if supply <= float(WATER_REQ):
        target *= 1.15

    # Convert to final bid bounded by budget.
    bid = min(budget, target)

    # Ensure non-negative.
    if bid < 0:
        bid = 0.0

    # If we have very low budget, still bid something to avoid being completely outcompeted.
    if budget > 0 and bid == 0.0:
        bid = min(budget, DAILY_SALARY * 0.2)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 1.0) if my_status['budget'] > 0 else 0.0

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    my_bid = DAILY_SALARY * 0.5

    # Aggressive bidding if desperate (low HP or missed water yesterday)
    if my_status['hp'] <= WATER_REQ * 2 or my_status['no_water_days'] > 0:
        my_bid = DAILY_SALARY * 0.9

    # React to opponents' previous bids
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= DAILY_SALARY * 0.6:
            my_bid = max(my_bid, highest_prev_bid + 2.0)
        else:
            my_bid = max(my_bid, DAILY_SALARY * 0.55)

    # Adjust based on supply scarcity and number of competitors
    total_water_needed_by_competitors = sum(opp['water_requirement'] for opp in alive_opponents)
    total_demand = WATER_REQ + total_water_needed_by_competitors

    if day_context['supply'] < total_demand * 0.8 and len(alive_opponents) > 0:
        my_bid = max(my_bid, DAILY_SALARY * 0.8)

    # End game pressure
    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 3 and my_status['hp'] <= WATER_REQ * 3:
        my_bid = max(my_bid, DAILY_SALARY * 0.95)

    final_bid = min(my_status['budget'], my_bid)

    if final_bid <= 0 and my_status['budget'] > 0 and my_status['hp'] > 0:
        final_bid = 1.0
    elif my_status['budget'] <= 0:
        final_bid = 0.0

    return final_bid

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    prev_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev['bid'])

    if not prev_bids:
        return min(my_status['budget'], DAILY_SALARY * 0.6)

    max_prev = max(prev_bids)
    avg_prev = sum(prev_bids) / len(prev_bids)

    if my_status['hp'] <= 3:
        return min(my_status['budget'], max(DAILY_SALARY * 1.1, max_prev * 1.05))

    if supply < 18:
        return min(my_status['budget'], max(DAILY_SALARY * 0.8, max_prev * 0.95))

    return min(my_status['budget'], max(DAILY_SALARY * 0.4, avg_prev * 0.8))
